      intro: "各位博士、管理员们好！我是 {operator}，{site}（zhoupmap.com）的运营者。{site}是我业余做的非官方同人小站，和鹰角网络没有关系。下面我用大白话跟大家讲清楚：我会收集你哪些信息、拿来做什么、别人能看到什么、存在哪里、存多久，以及你随时怎么把它们删掉。注册时勾选「我已阅读并同意隐私说明」，就表示你同意这里写的内容。另外有两件事会单独问你：注册时，同意把信息存到腾讯云香港服务器、由 Resend USA 发送验证码邮件；第一次放蟑螂前，同意公开它的确切位置。",
