        visitsB2: "不记 IP",
        passes: "{b}你抽到的每张通行证（哪个角色、编号、什么时候抽的）、你的心愿单和送券记录存在服务器上，只用来显示和防作弊。送券记录 7 天后删掉，其余的注销账号时一起删掉。",
        passesB: "寻访：",
        study: "{b}只记你一共学了几天、最近一次是哪天、今天抽到哪门课、今天这门没过关几次、是不是跳过了，和这一轮抽过哪几门（好让每门课轮完一遍才重复）；没登录时，这些只存在你自己的浏览器里。每一局只告诉服务器过没过关，成绩不上传（徒手写见下）；只有一局正好打出 325，或者在北京时间 3:25、15:25 那一分钟里上完一局时，会多告诉服务器一声，用来发两枚隐藏称号，别的不记；停表要先过一局看得见数字的，过没过只记在你自己的浏览器里，凑 325 最近出过的题（最多 200 道，好让它们先不重复）也是。地图上和触须之交都看不到你学没学，除非你自己发「苦也！」或「已完成今日的325大学习」这两句宣言，它们和别的宣言一样，附近的人看得到。徒手写：过了 60 分时，这张字会传给服务器再认一遍，只记下你过过，用来判断能不能给别人打分，字不存。你选了放上手写榜，才把这张字的笔画存下来，所有人都能看到，署名的话显示你在地图上的名字；撤下就删掉，注销账号也一起删。你给别人打的分，别人看不到是谁打的；作者只看到平均分、几个人评过和几个 799。",
        studyB: "325大学习：",
        listen: "{b}听歌时，你的手机从{site}的服务器下载歌。我们只记你现在在听哪首（给一起听和触须之交看「在听」用），不留听歌记录；每首歌只记一共放了多少次、每天一共被听满 30 秒多少次（做热播榜用，只留最近 8 天），都不记是谁。你收藏的歌存在服务器上，只有你自己看得见，取消收藏或注销账号就删掉。你的触须之交能看到你在听哪首，陌生人看不到；在「资料」里关掉「让触须之交看到我在听什么」，触须之交也看不到了。触须之交点「想一起听」时，你会收到一条消息，记下是谁、那时你在听哪首，两三天后删掉。一个人听时发的短评，只记这首歌每句一共被点了几次，不记是谁。一起听里，同一场的人能看到你的头像和名字（不是触须之交的人，看到的是陌生人能看到的样子）；短评只发给当时在这场的人，服务器不存。一起听散了一天后，这场有谁、放了哪些歌也删掉。发宣言一起听时，附近 {km} 公里内的舟P会看到你在听哪首；点「进去听」进来的人，和同一场的其他人一样能看到你。一起听开蹦迪「拉远」时，同一场里你的触须之交会在拉远的画面上看到你的蟑螂本体（就是地图上带心的那只本来所在的地方）；不是触须之交的人看不到。",
        listenB: "听歌：",
        squad: "{b}你开房间时选的服务器、难度和标签，和房间里每个人选的核心盟约和策略，登录的舟P在列表上能看到（显示房主的名字，和在卫戍名片里选了『列表上显示我的名字』的人的名字）；同盟密钥只给进了房间的人看。谁进过哪个房间、谁邀请了谁、谁请谁离开了房间、谁点了『准备』、每人这局标的核心盟约、策略和附加盟约、每人的蟑螂在房间里一直保持的动作，房间结束 24 小时后删除。快捷语句不保存，只记每天一共发了多少句；挥手、击掌、贴贴这些一下就完的动作也不保存。卫戍名片（核心盟约、策略、难度偏好，和列表上显示不显示名字）存在你的账号里，你进了房间才给别人看，清空或注销账号就删除。",
