      sewerfish: { name: "下水道鳞", use: "从龙门下水道游出来的鳞，颜色有点灰，身上挂着水草。", flavor: "近卫局查案的时候在下水道里见过它。它什么都知道，但什么都不说。" },
      fogfish: { name: "维多利亚雾鳞", use: "维多利亚起雾的日子才浮上来的鳞，颜色和雾差不多。", flavor: "伦蒂尼姆的雾大到看不见对岸，它就在雾里游了一整个下午。" },
